           name,
           placeholder,
           autocomplete
         };

         if (required) {
           inputAttributes.required = "required";
           inputAttributes["aria-required"] = "true";
         }

         if (inputMode) {
           inputAttributes.inputmode = inputMode;
         }

         let describedById = "";

         if (helperText) {
           describedById = `${id}-hint`;
           inputAttributes["aria-describedby"] = describedById;
         }

         const input = createElement("input", {
           attrs: inputAttributes
         });

         wrapper.append(fieldLabel, input);

         if (helperText) {
           wrapper.append(
             createElement("p", {
               className: "field-helper",
               text: helperText,
               attrs: { id: describedById }
             })
           );
         }

         return wrapper;
       };

